import{_ as o,o as t,c as d,a3 as a}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Tenant API v1 — ToDos","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — ToDos | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-todos"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — ToDos | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-todos"}]]},"headers":[],"relativePath":"api/tenant-v1-todos.md","filePath":"api/tenant-v1-todos.md","lastUpdated":1786141446000}'),c={name:"api/tenant-v1-todos.md"};function r(s,e,n,i,l,p){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="tenant-api-v1-—-todos" tabindex="-1">Tenant API v1 — ToDos <a class="header-anchor" href="#tenant-api-v1-—-todos" aria-label="Permalink to &quot;Tenant API v1 — ToDos&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>verified</code>, <code>module:todos</code>, plus permission middleware / policies.</p><p><strong>Creator scoping:</strong> without the workspace owner role (<code>superadmin</code>), list/board/show only include to-dos where <code>created_by</code> is the current user. The owner sees all tenant to-dos.</p><p><strong>Mutation rule:</strong> update and delete require the matching permission <strong>and</strong> <code>created_by ===</code> authenticated user (owners cannot mutate others’ to-dos).</p><h2 id="board" tabindex="-1">Board <a class="header-anchor" href="#board" aria-label="Permalink to &quot;Board&quot;">​</a></h2><h3 id="get-todos-board" tabindex="-1">GET <code>/todos/board</code> <a class="header-anchor" href="#get-todos-board" aria-label="Permalink to &quot;GET `/todos/board`&quot;">​</a></h3><p>One column per status (<code>open</code>, <code>in_progress</code>, <code>completed</code>, <code>cancelled</code>): <code>status</code>, <code>label</code>, <code>todo_count</code>, <code>todos[]</code>. Honors the same filters as list (<code>search</code>, <code>status</code>, <code>priority</code>, <code>my_todos</code>, <code>overdue</code>).</p><h2 id="todos-crud" tabindex="-1">ToDos CRUD <a class="header-anchor" href="#todos-crud" aria-label="Permalink to &quot;ToDos CRUD&quot;">​</a></h2><h3 id="get-todos" tabindex="-1">GET <code>/todos</code> <a class="header-anchor" href="#get-todos" aria-label="Permalink to &quot;GET `/todos`&quot;">​</a></h3><p>Query: <code>search</code>, <code>status</code>, <code>priority</code>, <code>my_todos</code>, <code>overdue</code>, <code>sort</code>, <code>direction</code>, <code>page</code>, <code>per_page</code>.</p><p>Status values: <code>open</code>, <code>in_progress</code>, <code>completed</code>, <code>cancelled</code>.<br> Priority values: <code>low</code>, <code>medium</code>, <code>high</code>, <code>urgent</code>.</p><p><code>overdue=true</code> returns open / in-progress to-dos with <code>due_at</code> in the past. When <code>overdue</code> is set, <code>status</code> is ignored.</p><h3 id="post-todos" tabindex="-1">POST <code>/todos</code> <a class="header-anchor" href="#post-todos" aria-label="Permalink to &quot;POST `/todos`&quot;">​</a></h3><p>Body: <code>title</code> (required), <code>description</code>, <code>status</code>, <code>priority</code>, <code>due_at</code>.</p><p><code>created_by</code> is set to the authenticated user.</p><h3 id="get-todos-id" tabindex="-1">GET <code>/todos/{id}</code> <a class="header-anchor" href="#get-todos-id" aria-label="Permalink to &quot;GET `/todos/{id}`&quot;">​</a></h3><p>Includes creator. Forbidden for non-owners who are not the creator.</p><h3 id="put-todos-id" tabindex="-1">PUT <code>/todos/{id}</code> <a class="header-anchor" href="#put-todos-id" aria-label="Permalink to &quot;PUT `/todos/{id}`&quot;">​</a></h3><p>Partial update of todo fields (including <code>status</code> / <code>priority</code> / <code>due_at</code>). Creator-only.</p><p>Setting status to <code>completed</code> sets <code>completed_at</code>; leaving completed clears it.</p><h3 id="delete-todos-id" tabindex="-1">DELETE <code>/todos/{id}</code> <a class="header-anchor" href="#delete-todos-id" aria-label="Permalink to &quot;DELETE `/todos/{id}`&quot;">​</a></h3><p>Soft delete. Permission: <code>todos.delete</code> <strong>and</strong> creator.</p>',23)])])}const m=o(c,[["render",r]]);export{u as __pageData,m as default};
